"295 :   private void processRequireCall(NodeTraversal t, Node n, Node parent) {
296 :     Node left = n.getFirstChild();
297 :     Node arg = left.getNext();
298 :     if (verifyLastArgumentIsString(t, left, arg)) {
299 :       String ns = arg.getString();
300 :       ProvidedName provided = providedNames.get(ns);
301 :       if (provided == null || !provided.isExplicitlyProvided()) {
302 :         unrecognizedRequires.add(
303 :             new UnrecognizedRequire(n, ns, t.getSourceName()));
304 :       } else {
305 :         JSModule providedModule = provided.explicitModule;
306 : 
307 :         // This must be non-null, because there was an explicit provide.
308 :         Preconditions.checkNotNull(providedModule);
309 : 
310 :         JSModule module = t.getModule();
311 :         if (moduleGraph != null &&
312 :             module != providedModule &&
313 :             !moduleGraph.dependsOn(module, providedModule)) {
314 :           compiler.report(
315 :               t.makeError(n, XMODULE_REQUIRE_ERROR, ns,
316 :                   providedModule.getName(),
317 :                   module.getName()));
318 :         }
319 :       }
320 : 
321 :       maybeAddToSymbolTable(left);
322 :       maybeAddStringNodeToSymbolTable(arg);
323 : 
324 :       // Requires should be removed before further processing.
325 :       // Some clients run closure pass multiple times, first with
326 :       // the checks for broken requires turned off. In these cases, we
327 :       // allow broken requires to be preserved by the first run to
328 :       // let them be caught in the subsequent run.
329 :       if (provided != null) {
330 :         parent.detachFromParent();
331 :         compiler.reportCodeChange();
332 :       }
333 :     }
